#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>

int main() {
    using namespace std;

    unsigned N;
    cin >> N;
    vector<unsigned> A(5 * N);
    for(auto&& a : A)cin >> a;

    nth_element(begin(A), begin(A) + N, end(A)); // 小さいほうから N 個を除く
    nth_element(begin(A) + N, end(A) - N, end(A)); // 大きいほうから N 個を除く

    cout << reduce(begin(A) + N, end(A) - N) / static_cast<long double>(3 * N) << endl;

    return 0;
}
